// Demonstration of fractal graphics. Mandelbrot set
// For each point of the complex plane z=(x,y) perform iterative process z=z*2+c, c=(cx,cy)
// Count the number of iterations i until the condition |z|>max is met
// Then draw point z=(x,y) with red color saturation proportional to i
uses GraphABC;

const
  max = 10;
  coef1 = 0.5;
  coef2 = 0.88;
  scalex = 0.0035;
  scaley = 0.0035;
  dx = 430;
  dy = 300;

begin
  Window.Title := 'Fractals: Mandelbrot set';
  SetWindowSize(600,600);
  CenterWindow;
  for var ix:=0 to Window.Width-1 do
  for var iy:=0 to Window.Height-1 do
  begin
    var z := Cplx(0,0);

    var i := 1;
    while i<255 do
    begin
      z := z * z + 0.0035 * Cplx(ix - 430,iy - 300); 
      if z.Magnitude>10 then break;
      i += 1;
    end;
    if i>=255 then SetPixel(ix,iy,clRed)
      else SetPixel(ix,iy,RGB(255,255-i,255-i));
  end;
  writeln('Calculation time = ',Milliseconds/1000,' s');
end.

