// 1. Full forms of function definitions.

// 1.1. Function without parameters.
function EmptyFunc : integer;
begin
  Result := 0;
  for var i := 1 to 10 do
    Result += i;
end;

// 1.2. Function with several parameters of different types.
function RegularFunc(x : real; n : integer): real;
begin
  Result := 1.0;
  var Elem := 1.0;
  for var i := 1 to n do
  begin
    Elem *= x / i;
    Result += Elem;
  end;
end;

// 1.3. Function returning multiple parameters via tuple.
function TupleFunc(x, y: integer): (integer, integer);
begin
  Result := (x + y, x - y); // form a tuple
end;

// 2. Shortened forms of function definitions.

// 2.1. Shortened form of a regular function (with auto type inference).
function ShortRegularFuncAuto(a, b: real) := a + b; // return sum, but without type

// 2.2. Shortened form of a regular function (without auto type inference).
function ShortRegularFuncNoAuto(a, b: real) : real := a + b; // return sum, but hint the type

// 2.3. Shortened form of a function returning a tuple of 2 integers (with auto type inference).
function ShortTupleFuncAuto(x, y: integer) := (x + y, x - y); // immediately return tuple

// 2.4. Shortened form of a function returning a tuple of 2 integers (without auto type inference).
function ShortTupleFuncNoAuto(x, y: integer) : (integer, integer) := (x + y, x - y); // hint the type

begin
  // 1.1.
  var sum1 := EmptyFunc; // call function without parameters
  Println($'Sum of numbers from 1 to 10 = {sum1}'); Println;

  // 1.2.
  var (x2, n2) := (1.0, 1000); 
  var sum_exp := RegularFunc(x2, n2); // calculate exponent via Taylor series at point x2 with n2 terms
  Println($'Exact value of Exp({x2}) = {Exp(x2)}');
  Println($'Approximate value with {n2} terms = {sum_exp}');
  Println($'Absolute difference = {Abs(Exp(x2) - sum_exp)}'); Println;

  // 1.3.
  var (x3, y3) := (1, 2);
  var (sum3, subtract3) := TupleFunc(x3, y3); // call function returning tuple
  Println($'Sum: {x3} + {y3} = {sum3}, {x3} - {y3} = {subtract3}'); Println;

  // 2.1. (2.2. similar)
  var (x4, y4) := (1.3, 2.2);
  var sum4 := ShortRegularFuncAuto(x4, y4); // call function from section 2.1
  Println($'Sum: {x4} + {y4} = {sum4}.'); Println;

  // 2.3. (2.4. similar)
  var (x5, y5) := (10, 20);
  var (sum5, subtract5) := ShortTupleFuncAuto(x5, y5); // call function from section 2.3
  Println($'Sum: {x5} + {y5} = {sum5}, {x5} - {y5} = {subtract5}');
end.

