begin
  // Returns an array
  var d := [s for s in stud where s.Age>20 orderby s.Name];
  // Returns a sequence
  var seq := s for s in stud where s.Age>20 orderby s.Name;
  // i.e., take sequence in [] and get array - if I can handle the grammar
  var a := [a.Where(x->x>0)];

  // List comprehension syntax variants

  // Alternative 0 - LINQ C#
  var a := for x in a where x>0 select x*x;
  // Alternative 1 - almost like LINQ
  var a := [x*x from x in a where x>0];
  // Alternative 2 - if WHAT is not specified, take expression after for
  var a := [for x in a where x>0];
  // Alternative 3 - a bit mathematical notation
  var a := [x*x: for x in 1..10 where x.IsOdd];
  // Alternative 4 - Nemerle, mathematical notation, but then orderby is unclear how to attach
  var a := [x*x: x in 1..10, x.IsOdd];
  // Alternative 5 - Julia and Python - word if
