/// Gets a sequence from an initial value
function Unfold<T,T1>(initial: T; next: T->(T1,T,boolean)): sequence of T1; 
begin
  var q := next(initial);
  while q[2] do
  begin
    yield q[0];
    initial := q[1];
    q := next(initial);
  end;
end;

/// Gets a sequence from an initial value
function Unfold<T,T1>(initial: T; proj: T->T1; next: T->T; cond: T->boolean): sequence of T1; 
begin
  while cond(initial) do
  begin
    yield proj(initial);
    initial := next(initial);
  end;
end;

/// Gets a sequence from an initial value
function Unfold<T>(initial: T; next: T->T; cond: T->boolean): sequence of T; 
begin
  while cond(initial) do
  begin
    yield initial;
    initial := next(initial);
  end;
end;

/// Gets a sequence from an initial value
function Unfold<T>(initial: T; next: T->(T,boolean)): sequence of T; 
begin
  var q := next(initial);
  while q[1] do
  begin
    yield initial;
    initial := q[0];
    q := next(initial);
  end;
end;

/// Gets an infinite sequence from an initial value
function UnfoldInf<T,T1>(x: T; next: T->(T1,T)): sequence of T1;
begin
  while True do
  begin
    var q := next(x);
    yield q[0];
    x := q[1];
  end;
end;

/// Gets an infinite sequence from an initial value
function UnfoldInf<T,T1>(initial: T; proj: T->T1; next: T->T): sequence of T1;
begin
  while True do
  begin
    yield proj(initial);
    initial := next(initial);
  end;
end;

