function GetTopKMaximums(arr: array of integer; k: integer): array of integer;
begin
  // Min-heap (priority queue)
  var minHeap := new SortedSet<integer>(arr.Take(k));

  // Process remaining array elements
  for var i := k to arr.Length - 1 do
    if arr[i] > minHeap.Min then
    begin
      minHeap.Remove(minHeap.Min); // Remove minimum from heap
      minHeap.Add(arr[i]); // Add new element
    end;

  // Convert heap to array
  Result := arr.Where(x -> x in minHeap).OrderDescending.ToArray
end;

begin
  var arr := [3, 1, 4, 2, 5, 9, 7, 7, 6];
  var k := 4; // Number of maximums
  var topKMaximums := GetTopKMaximums(arr, k);
  // Output result
  Print($'Top {k} maximum(s):', topKMaximums);
end.

type
  // Define auto class for storing point data
  Point = auto class
    Features: array of Real; // Point features
    &Label: String; // Class label, escaped with &

