type
  SortedMultiset<T> = class(IEnumerable<T>)
  private
    data := new SortedDictionary<T, integer>; // Store element and its occurrence count

  public
    // Method to add element
    procedure Add(x: T);
    begin
      if x in data then
        data[x] += 1 // Increase occurrence count
      else data.Add(x, 1); // Add new element with count 1
    end;

    // Method to remove element
    function Remove(x: T): boolean;
    begin
      if x in data then
      begin
        if data[x] > 1 then
          data[x] -= 1 // Decrease occurrence count
        else data.Remove(x); // Remove element if last occurrence
        Result := true;
      end
      else Result := false;
    end;

    // Method to get occurrence count of element
    function Count(x: T): integer;
    begin
      if x in data then
        Result := data[x]
      else Result := 0;
    end;

    // Method to get minimum element
    function Min: T;
    begin
      if data.Count = 0 then
        raise new System.InvalidOperationException('Multiset is empty.');
      Result := data.Keys.First(); // First element in sorted set
    end;

    // Method to get maximum element
    function Max: T;
    begin
      if data.Count = 0 then
        raise new System.InvalidOperationException('Multiset is empty.');
      Result := data.Keys.Last(); // Last element in sorted set
    end;

    // Method to get all elements of the set
    function GetElements: sequence of T;
    begin
      foreach var key in data.Keys do
        for var i := 1 to data[key] do
          yield key;
    end;

    // Implementation of IEnumerable<T> interface
    function GetEnumerator: IEnumerator<T>;
    begin
      Result := GetElements().GetEnumerator();
    end;

    function System.Collections.IEnumerable.GetEnumerator: System.Collections.IEnumerator;
    begin
      Result := GetElements().GetEnumerator();
    end;
  end;

// Usage example
begin
  var multiset := new SortedMultiset<integer>();
  multiset.Add(5);
  multiset.Add(3);
  multiset.Add(5);
  multiset.Add(2);

  multiset.Print(); // Output: 2 3 5 5

  multiset.Remove(5);
  multiset.Print(); // Output: 2 3 5

  Writeln('Min: ', multiset.Min); // Output: Min: 2
  Writeln('Max: ', multiset.Max); // Output: Max: 5
  Writeln('Count of 5: ', multiset.Count(5)); // Output: Count of 5: 1

  // Use in foreach loop
  foreach var elem in multiset do
    Writeln('Element: ', elem);

  multiset.Println;
end.

