function BisectionMethod(a, b, eps: real): real;
begin
  var fa := f(a); // Compute f(a) once at the beginning
  while abs(b - a) > eps do
  begin
    var c := (a + b) / 2;
    var fc := f(c); // Compute function only once per iteration
    if fc = 0 then
      break; // Exit loop if exact root found
    if fa * fc < 0 then
      b := c
    else
      (a, fa) := (c, fc); // Tuple assignment
  end;
  Result := (a + b) / 2; // Return midpoint as approximate root
end;

