// Prediction: ŷ = w1*x1 + w2*x2 + b
function Predict(x1, x2, w1, w2, b: real) := w1 * x1 + w2 * x2 + b;

// Quadratic loss
function Loss(pred, y: real) := Sqr(pred - y);

// Gradients
function d_w1(x1, pred, y: real) := 2 * x1 * (pred - y);
function d_w2(x2, pred, y: real) := 2 * x2 * (pred - y);
function d_b(pred, y: real) := 2 * (pred - y);

begin
  // Data: [preparation hours, sleep hours] -> score
  var x: array of array of real := (
    (2, 6), (4, 5), (5, 7), (1, 4), (3, 6),
    (6, 5), (5, 6), (7, 8), (3, 5), (4, 7));
  var y: array of real := (70, 78, 82, 62, 75, 85, 80, 90, 72, 79);
  var n := x.Length;

  // Model parameters
  var w1 := 0.1;
  var w2 := 0.1;
  var b := 0.1;

  var lr := 0.005;      // learning rate (slightly larger for faster convergence)
  var epochs := 20000;   // more epochs for deeper convergence

  var errors := new real[epochs];

  for var epoch := 0 to epochs - 1 do
  begin
    var total_loss := 0.0;
    var grad_w1 := 0.0;
    var grad_w2 := 0.0;
    var grad_b := 0.0;

    // accumulate sum over entire dataset (batch)
    for var i := 0 to n - 1 do
    begin
      var p := Predict(x[i][0], x[i][1], w1, w2, b);
      total_loss += Loss(p, y[i]);
      grad_w1 += d_w1(x[i][0], p, y[i]);
      grad_w2 += d_w2(x[i][1], p, y[i]);
      grad_b += d_b(p, y[i]);
    end;

    // update parameters by average gradient
    w1 -= lr * grad_w1 / n;
    w2 -= lr * grad_w2 / n;
    b -= lr * grad_b / n;

    // average loss per epoch
    errors[epoch] := total_loss / n;

    // log every 1000 epochs
    if ((epoch + 1) mod 1000 = 0) then
      Println($'Epoch {epoch+1}: loss = {errors[epoch]:0.0000}; w1={w1:0.000}, w2={w2:0.000}, b={b:0.000}');
  end;

  Println;
  Println('Model testing:');
  var tests: array of array of real := (
    (4, 6),  // average student
    (6, 5),  // studied well
    (2, 8)   // studied little but slept well
  );

  for var i := 0 to tests.GetLength(0) - 1 do
  begin
    var tx1 := tests[i, 0];
    var tx2 := tests[i, 1];
    var p := Predict(tx1, tx2, w1, w2, b);
    Println($'Preparation={tx1} h, Sleep={tx2} h → predicted: {Round(p, 2)} points');
  end

end.

