begin
  var s := 'Treasure is buried in [south-west] under [palm tree]';
  var searchWord := 'hidden';

  var searchPos := 0;  

  while True do
  begin
    var startPos := s.IndexOf('[', searchPos);  
    if startPos = -1 then break;                

    var endPos := s.IndexOf(']', startPos + 1); 
    if endPos = -1 then break;                  

    var removeStart := startPos + 1;
    var length := endPos - startPos - 1;

    s := s.Remove(removeStart, length);

    s := s.Insert(removeStart, searchWord);

    searchPos := removeStart + searchWord.Length;
  end;

  Println(s);
end.

begin
  var s := 'Treasure is buried in [south-west] under [palm tree]';
  var replaceStr := 'hidden';

  var startPos := s.IndexOf('[');
  while startPos <> -1 do
  begin
    var endPos := s.IndexOf(']', startPos + 1);
    if endPos = -1 then break;

    s := s.Remove(startPos + 1, endPos - startPos - 1);
    s := s.Insert(startPos + 1, replaceStr);

    startPos := s.IndexOf('[', endPos);
  end;

  Println(s);
end.

