function SieveOfEratosthenes(n: integer): array of integer;
begin
  var isPrime := [False] * 2 + [True] * (n - 1); 

  for var i := 2 to ISqrt(n) do
    if isPrime[i] then
      for var j := i * i to n step i do
        isPrime[j] := False;

  Result := (2..n).Where(i -> isPrime[i]).ToArray;
end;

SieveOfEratosthenes(1000).Println;

type 
  Product = auto class
    Category: string;
    Model: string;    
    Price: real;
    Rating: real;
  end;

begin
  var products := 
    [
      new Product('Phones', 'iPhone 13', 499.99, 4.5),
      new Product('Phones', 'Galaxy S21', 699.99, 4.7),
      new Product('Phones', 'iPhone 13', 299.99, 4.2),  
      new Product('Laptops', 'MacBook Pro', 999.99, 4.8),
      new Product('Laptops', 'MacBook Pro', 1299.99, 4.9), 
      new Product('Tablets', 'iPad Air', 399.99, 4.3),
      new Product('Tablets', 'iPad Air', 399.99, 4.3)   
    ];

  // 1. Number of unique models by category
  var uniqueModels := products
    .GroupBy(p -> p.Category)
    .Each(g -> g.DistinctBy(p -> p.Model).Count);

  // 2. Average price by category
  var avgPrices := products
    .GroupBy(p -> p.Category)
    .Each(g -> g.Average(p -> p.Price));

  // 3. Total count of products by category
  var totalCounts := products
    .GroupBy(p -> p.Category)
    .Each(g -> g.Count);

  Println('Unique models by category:');
  uniqueModels.PrintLines(kv -> $'  {kv.Key}: {kv.Value}');

  Println('Average price by category:');
  avgPrices.PrintLines(kv -> $'  {kv.Key}: ${kv.Value:F2}');

  Println('Total products by category:');
  totalCounts.PrintLines(kv -> $'  {kv.Key}: {kv.Value}');
end.
